/**
 * cards — a set of repeating text units (one row per card).
 *
 * Variants (same content model, different skin):
 *   - cards steps   : 3-up grid, auto-numbered 01/02/03, accent rule under the title
 *   - cards anchors : stacked list, auto-numbered i./ii./iii., hairline separators
 *
 * Authoring: one row per card; the cell holds an <h3> title and body paragraph(s),
 * optionally a picture. The section head (eyebrow + <h2>) is DEFAULT CONTENT above
 * the block. Numbering is generated by CSS counters (decorative, not authored).
 */
export default async function decorate(block) {
  const ol = document.createElement('ol');
  ol.className = 'cards-list';
  [...block.children].forEach((row) => {
    const li = document.createElement('li');
    li.className = 'cards-card';
    [...row.children].forEach((cell) => {
      const body = document.createElement('div');
      const onlyMedia = cell.children.length === 1 && cell.querySelector('picture, img');
      body.className = onlyMedia ? 'cards-card-image' : 'cards-card-body';
      body.append(...cell.childNodes);
      if (body.childNodes.length) li.append(body);
    });
    if (li.children.length) ol.append(li);
  });
  block.replaceChildren(ol);
}
